package {
    // See: http://go/android-license-faq
    // A large-scale-change added 'default_applicable_licenses' to import
    // all of the 'license_kinds' from "hardware_interfaces_license"
    // to get the below license kinds:
    //   SPDX-license-identifier-Apache-2.0
    default_applicable_licenses: ["hardware_interfaces_license"],
}

cc_binary {
    name: "android.hardware.automotive.audiocontrol-service.example",
    relative_install_path: "hw",
    init_rc: ["audiocontrol-default.rc"],
    vintf_fragments: ["audiocontrol-default.xml"],
    vendor: true,
    defaults: [
        "latest_android_hardware_audio_common_ndk_shared",
        "latest_android_hardware_automotive_audiocontrol_ndk_shared",
        "powerpolicyclient_defaults",
        "car.audio.configuration.xsd.default",
        "car.fade.configuration.xsd.default",
    ],
    shared_libs: [
        "android.hardware.audio.common@7.0-enums",
        "libbinder_ndk",
        "libcutils",
        "liblog",
        "libbase",
        "libxml2",
        "libutils",
        "android.hardware.audiocontrol.internal",
        "libaudio_aidl_conversion_common_ndk",
    ],
    srcs: [
        "AudioControl.cpp",
        "main.cpp",
        "PowerPolicyClient.cpp",
    ],
}
